import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './../css/AddLoan.css'; // Correct path to AddLoan.css

const AddLoan = () => {
  const [formData, setFormData] = useState({
    CustomerID: '',
    fullname: '',
    email: '',
    nic: '',
    garantter1: '',
    garantter1id: '',
    garantter1address: '',
    garantter2: '',
    garantter2id: '',
    garantter2address: '',
    amount: '',
    installment: '',
    installmentrate: '',
    interest: '',
    loanEndDate: '',
    createDate: new Date().toISOString().split('T')[0], // Default to today's date
    loanDuration: '',
    loanType: '', // New field
  });
  const [customers, setCustomers] = useState([]);
  const [statusMessage, setStatusMessage] = useState({ type: '', text: '' });

  useEffect(() => {
    const fetchCustomers = async () => {
      try {
        const response = await axios.get('https://hiru-captial-investment.onrender.com/api/customers');
        setCustomers(response.data);
      } catch (error) {
        console.error('Error fetching customers:', error);
      }
    };

    fetchCustomers();
  }, []);

  // Auto-calculate interest when relevant fields change
  useEffect(() => {
    const { amount, installmentrate, loanDuration, loanType } = formData;
    if (amount && installmentrate && loanDuration && loanType) {
      const principal = parseFloat(amount);
      const monthlyRate = parseFloat(installmentrate) / 100;
      let months = 1;
      if (loanType === 'Daily') {
        months = parseFloat(loanDuration) / 30;
      } else if (loanType === 'Weekly') {
        months = parseFloat(loanDuration) / 4;
      }
      const calculatedInterest = principal * monthlyRate * months;
      setFormData((prevData) => ({
        ...prevData,
        interest: calculatedInterest.toFixed(2),
      }));
    } else {
      setFormData((prevData) => ({
        ...prevData,
        interest: '',
      }));
    }
  }, [formData]); // <-- Fix: add formData as dependency

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prevData) => ({ ...prevData, [name]: value }));

    if (name === 'fullname') {
      const selectedCustomer = customers.find((customer) => customer.fullName === value);
      if (selectedCustomer) {
        setFormData((prevData) => ({
          ...prevData,
          CustomerID: selectedCustomer._id,
          nic: selectedCustomer.idNumber,
        }));
      }
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post('https://hiru-captial-investment.onrender.com/api/loan/createLoan', formData, {
        headers: {
          'Content-Type': 'application/json',
        },
      });

      setStatusMessage({ type: 'success', text: response.data.message });

      // Clear the form
      setFormData({
        CustomerID: '',
        fullname: '',
        email: '',
        nic: '',
        garantter1: '',
        garantter1id: '',
        garantter1address: '',
        garantter2: '',
        garantter2id: '',
        garantter2address: '',
        amount: '',
        installment: '',
        installmentrate: '',
        interest: '',
        loanEndDate: '',
        createDate: new Date().toISOString().split('T')[0], // Reset to today's date
        loanDuration: '',
        loanType: '',
      });
    } catch (error) {
      console.error('Error:', error);
      setStatusMessage({ type: 'error', text: error.response?.data?.message || 'Failed to add loan. Please try again.' });
    }
  };

  return (
    <div className="add-loan">
      <h2>Add Loan</h2>

      {statusMessage.text && (
        <div className={`status-message ${statusMessage.type}`}>
          {statusMessage.text}
        </div>
      )}

      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="fullname">Full Name</label>
          <select
            id="fullname"
            name="fullname"
            value={formData.fullname}
            onChange={handleChange}
            required
          >
            <option value="">Select Customer</option>
            {customers.map((customer) => (
              <option key={customer._id} value={customer.fullName}>
                {customer.fullName}
              </option>
            ))}
          </select>
        </div>
        <div className="form-group">
          <label htmlFor="nic">NIC</label>
          <input
            type="text"
            id="nic"
            name="nic"
            value={formData.nic}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="email">Email</label>
          <input
            type="email"
            id="email"
            name="email"
            value={formData.email}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="garantter1">Guarantor 1</label>
          <input
            type="text"
            id="garantter1"
            name="garantter1"
            value={formData.garantter1}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="garantter1id">Guarantor 1 ID</label>
          <input
            type="text"
            id="garantter1id"
            name="garantter1id"
            value={formData.garantter1id}
